import * as bcrypt from 'bcryptjs';
import * as jwt from 'jsonwebtoken';

// --- In-memory Data Stores ---
// For demonstration purposes, in a real application, these would be persisted in a database.
interface User {
  id: string;
  email: string;
  passwordHash: string;
  role?: string;
}

interface LoginAttempt {
  count: number;
  lastAttempt: number; // Timestamp
  blockedUntil?: number; // Timestamp
}

const USERS_DB = new Map<string, User>(); // Key: email, Value: User
const LOGIN_ATTEMPTS_DB = new Map<string, LoginAttempt>(); // Key: IP address or email, Value: LoginAttempt

// --- Configuration Constants ---
const JWT_SECRET = process.env.JWT_SECRET || 'supersecretjwtkeythatshouldbechangedinproduction';
const JWT_EXPIRATION_TIME = '1h';
const BCRYPT_SALT_ROUNDS = 10;

const MAX_LOGIN_ATTEMPTS = 5;
const BLOCK_DURATION_MS = 5 * 60 * 1000; // 5 minutes

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

export class AuthService implements IAuthService {
  constructor() {
    // Seed a dummy user for testing
    if (!USERS_DB.has('test@example.com')) {
      this.hashPassword('password123').then(hash => {
        USERS_DB.set('test@example.com', {
          id: 'user123',
          email: 'test@example.com',
          passwordHash: hash,
          role: 'user',
        });
      });
    }
  }

  public async hashPassword(password: string): Promise<string> {
    return bcrypt.hash(password, BCRYPT_SALT_ROUNDS);
  }

  public async verifyPassword(password: string, hash: string): Promise<boolean> {
    return bcrypt.compare(password, hash);
  }

  public async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    return jwt.sign(payload, secret, { expiresIn: JWT_EXPIRATION_TIME });
  }

  public async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const { email, password, ip } = request;
    const now = Date.now();

    if (!email || !password) {
      return { status: 400, body: { message: 'Email and password are required.' } };
    }

    // Rate limiting check based on IP
    const ipAttempt = LOGIN_ATTEMPTS_DB.get(ip || 'unknown_ip');
    if (ipAttempt && ipAttempt.blockedUntil && ipAttempt.blockedUntil > now) {
      return { status: 429, body: { message: 'Too many login attempts. Please try again later.' } };
    }

    const user = USERS_DB.get(email);

    if (!user || !(await this.verifyPassword(password, user.passwordHash))) {
      // Increment failed attempts for IP
      const currentIpAttempt = LOGIN_ATTEMPTS_DB.get(ip || 'unknown_ip') || { count: 0, lastAttempt: now };
      currentIpAttempt.count++;
      currentIpAttempt.lastAttempt = now;

      if (currentIpAttempt.count >= MAX_LOGIN_ATTEMPTS) {
        currentIpAttempt.blockedUntil = now + BLOCK_DURATION_MS;
        currentIpAttempt.count = 0; // Reset count after blocking
      }
      LOGIN_ATTEMPTS_DB.set(ip || 'unknown_ip', currentIpAttempt);

      // Increment failed attempts for email (optional, for more granular blocking)
      const currentEmailAttempt = LOGIN_ATTEMPTS_DB.get(email) || { count: 0, lastAttempt: now };
      currentEmailAttempt.count++;
      currentEmailAttempt.lastAttempt = now;
      if (currentEmailAttempt.count >= MAX_LOGIN_ATTEMPTS) {
        currentEmailAttempt.blockedUntil = now + BLOCK_DURATION_MS;
        currentEmailAttempt.count = 0;
      }
      LOGIN_ATTEMPTS_DB.set(email, currentEmailAttempt);

      return { status: 401, body: { message: 'Invalid credentials.' } };
    }

    // Successful login: Clear rate limit attempts for this IP and email
    LOGIN_ATTEMPTS_DB.delete(ip || 'unknown_ip');
    LOGIN_ATTEMPTS_DB.delete(email);

    const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, JWT_SECRET);
    return { status: 200, body: { message: 'Login successful', token } };
  }
}

