import * as bcrypt from 'bcrypt';
import * as jwt from 'jsonwebtoken';
import * as crypto from 'node:crypto';

// Define constants for security and rate limiting
const BCRYPT_SALT_ROUNDS = 12; // OWASP recommendation >= 12
const JWT_EXPIRATION_SECONDS = 15 * 60; // 15 minutes for access tokens
const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 15 * 60 * 1000; // 15 minutes

// In-memory storage for rate limiting and lockout
interface LoginAttempt {
  count: number;
  lastAttempt: number;
  lockedUntil?: number;
}
const loginAttempts = new Map<string, LoginAttempt>(); // Key: IP address or email

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

export class AuthService implements IAuthService {
  constructor(private readonly getUserFn: (email: string) => Promise<{ id: string; email: string; passwordHash: string; role?: string } | null>) {}

  async hashPassword(password: string): Promise<string> {
    // Node.js skill rule: Use async crypto calls
    return bcrypt.hash(password, BCRYPT_SALT_ROUNDS);
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    // Node.js skill rule: Use async crypto calls
    // Security skill rule: Use timingSafeEqual for secrets if comparing raw hashes, but bcrypt.compare handles this internally.
    return bcrypt.compare(password, hash);
  }

  async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    // Security skill rule: Short-lived access tokens
    return new Promise((resolve, reject) => {
      jwt.sign(payload, secret, { expiresIn: JWT_EXPIRATION_SECONDS }, (err, token) => {
        if (err) {
          return reject(new Error('Failed to generate token'));
        }
        if (!token) {
          return reject(new Error('Token generation resulted in empty token'));
        }
        resolve(token);
      });
    });
  }

  async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const { email, password, ip } = request;

    // Ponytail mindset: Input validation is sacred
    if (!email || !password) {
      return { status: 400, body: { message: 'Email and password are required.' } };
    }

    const identifier = email.toLowerCase(); // Use email as identifier for lockout, or IP if preferred for broader rate limiting

    // Security skill rule: Enforce rate limiting and brute-force lockouts
    const attempt = loginAttempts.get(identifier) || { count: 0, lastAttempt: 0 };
    const now = Date.now();

    if (attempt.lockedUntil && now < attempt.lockedUntil) {
      // Security skill rule: Never return raw internal errors, provide generic message
      return { status: 429, body: { message: 'Too many login attempts. Please try again later.' } };
    }

    // Reset attempt count if lockout duration has passed since last attempt
    if (now - attempt.lastAttempt > LOCKOUT_DURATION_MS) {
      attempt.count = 0;
      attempt.lockedUntil = undefined;
    }

    attempt.lastAttempt = now;
    loginAttempts.set(identifier, attempt);

    try {
      const user = await this.getUserFn(identifier);

      if (!user || !(await this.verifyPassword(password, user.passwordHash))) {
        attempt.count++;
        if (attempt.count >= MAX_LOGIN_ATTEMPTS) {
          attempt.lockedUntil = now + LOCKOUT_DURATION_MS;
          // Log this lockout event internally for monitoring
          console.warn(`User ${identifier} locked out due to too many failed login attempts.`);
        }
        loginAttempts.set(identifier, attempt);
        // Security skill rule: Generic error message to prevent enumeration attacks
        return { status: 401, body: { message: 'Invalid credentials.' } };
      }

      // If login successful, reset attempts for this identifier
      loginAttempts.delete(identifier);

      // Generate a random secret for JWT signing (in a real app, this would come from config/env)
      // For this self-contained example, we'll use a simple static secret.
      // In production, use a strong, environment-variable-based secret.
      const jwtSecret = process.env.JWT_SECRET || 'super-secret-jwt-key-change-me-in-prod';
      const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, jwtSecret);

      return { status: 200, body: { message: 'Login successful.', token } };
    } catch (error) {
      // Security skill rule: Never return raw database/internal error messages
      console.error('Login error:', error); // Log detailed error internally
      return { status: 500, body: { message: 'An unexpected error occurred during login.' } };
    }
  }
}

