export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class Money {
  readonly amount: number;
  readonly currency: string;

  private constructor(amount: number, currency: string) {
    if (amount < 0) {
      throw new Error("Money amount cannot be negative.");
    }
    if (!currency || currency.trim() === '') {
      throw new Error("Money currency cannot be empty.");
    }
    this.amount = parseFloat(amount.toFixed(2)); // Ensure 2 decimal places
    this.currency = currency.toUpperCase();
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new Error("Cannot add Money with different currencies.");
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    if (!(other instanceof Money)) {
      return false;
    }
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

// Domain Event Base (simplified for this exercise)
interface DomainEvent {
  readonly type: string;
  readonly occurredOn: Date;
  readonly aggregateId: string;
}

class OrderCreatedEvent implements DomainEvent {
  readonly type = 'OrderCreated';
  readonly occurredOn = new Date();
  constructor(public readonly aggregateId: string, public readonly customerId: string) {}
}

class OrderItemAddedEvent implements DomainEvent {
  readonly type = 'OrderItemAdded';
  readonly occurredOn = new Date();
  constructor(public readonly aggregateId: string, public readonly itemId: string, public readonly productId: string, public readonly quantity: number, public readonly price: Money) {}
}

class OrderPaidEvent implements DomainEvent {
  readonly type = 'OrderPaid';
  readonly occurredOn = new Date();
  constructor(public readonly aggregateId: string) {}
}

class OrderShippedEvent implements DomainEvent {
  readonly type = 'OrderShipped';
  readonly occurredOn = new Date();
  constructor(public readonly aggregateId: string) {}
}

class OrderCancelledEvent implements DomainEvent {
  readonly type = 'OrderCancelled';
  readonly occurredOn = new Date();
  constructor(public readonly aggregateId: string) {}
}

export class Order {
  readonly id: string;
  private _status: OrderStatus;
  private _items: OrderItem[];
  private _domainEvents: DomainEvent[] = [];
  private readonly customerId: string; // Added for completeness, though not in interface

  constructor(id: string, customerId: string) {
    this.id = id;
    this.customerId = customerId;
    this._status = 'PENDING';
    this._items = [];
    this._domainEvents.push(new OrderCreatedEvent(this.id, this.customerId));
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new Error("Cannot add items to an order that is not PENDING.");
    }
    if (quantity <= 0) {
      throw new Error("Quantity must be positive.");
    }
    const newItem: OrderItem = {
      id: `${this.id}-${this._items.length + 1}`, // Simple unique ID for item
      quantity,
      price,
    };
    this._items.push(newItem);
    this._domainEvents.push(new OrderItemAddedEvent(this.id, newItem.id, productId, quantity, price));
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new Error("Order can only be paid if its status is PENDING.");
    }
    if (this._items.length === 0) {
      throw new Error("Cannot pay for an empty order.");
    }
    this._status = 'PAID';
    this._domainEvents.push(new OrderPaidEvent(this.id));
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new Error("Order can only be shipped if its status is PAID.");
    }
    this._status = 'SHIPPED';
    this._domainEvents.push(new OrderShippedEvent(this.id));
  }

  cancel(): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new Error("Order cannot be cancelled if it is SHIPPED or already CANCELLED.");
    }
    this._status = 'CANCELLED';
    this._domainEvents.push(new OrderCancelledEvent(this.id));
  }

  getTotal(): Money {
    if (this._items.length === 0) {
      return Money.of(0, this._items[0]?.price.currency || 'USD'); // Default to USD if no items
    }
    const currency = this._items[0].price.currency;
    let totalAmount = 0;
    for (const item of this._items) {
      if (item.price.currency !== currency) {
        throw new Error("Items in order have different currencies.");
      }
      totalAmount += item.price.amount * item.quantity;
    }
    return Money.of(totalAmount, currency);
  }

  getDomainEvents(): DomainEvent[] {
    const events = [...this._domainEvents];
    this._domainEvents = []; // Clear events after retrieval
    return events;
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

// In-memory implementation for demonstration
class InMemoryOrderRepository implements IOrderRepository {
  private orders = new Map<string, Order>();

  async findById(id: string): Promise<Order | null> {
    // Deep copy to prevent external modification of the aggregate's internal state
    // In a real scenario, this would involve deserialization from a database.
    const order = this.orders.get(id);
    if (!order) return null;

    // Simplified deep copy for demonstration.
    // A proper rehydration would reconstruct the Order object from raw data.
    const rehydratedOrder = new Order(order.id, (order as any).customerId); // Access private customerId
    (rehydratedOrder as any)._status = order.status;
    (rehydratedOrder as any)._items = order.items.map(item => ({
      ...item,
      price: Money.of(item.price.amount, item.price.currency)
    }));
    (rehydratedOrder as any)._domainEvents = []; // Rehydrated orders start with no pending events
    return rehydratedOrder;
  }

  async save(order: Order): Promise<void> {
    // In a real scenario, this would involve serialization to a database.
    // We store a copy to simulate persistence and prevent direct modification
