export interface OrderItem {
  readonly id: string; // Product ID
  readonly quantity: number;
  readonly price: Money; // Price per unit
}

interface DomainEvent {
  readonly type: string;
  readonly occurredAt: Date;
  readonly payload: Record<string, unknown>;
}

export class Order {
  public readonly id: string;
  public readonly customerId: string;
  public status: OrderStatus;
  public readonly items: ReadonlyArray<OrderItem>;
  private _items: OrderItem[];
  private domainEvents: DomainEvent[];

  constructor(id: string, customerId: string) {
    if (!id || id.trim() === '') {
      throw new Error('Order ID cannot be empty.');
    }
    if (!customerId || customerId.trim() === '') {
      throw new Error('Customer ID cannot be empty.');
    }
    this.id = id;
    this.customerId = customerId;
    this.status = 'PENDING';
    this._items = [];
    this.items = this._items; // Expose as ReadonlyArray
    this.domainEvents = [];
  }

  public addItem(productId: string, quantity: number, price: Money): void {
    if (this.status !== 'PENDING') {
      throw new Error('Cannot add items to an order that is not PENDING.');
    }
    if (quantity <= 0) {
      throw new Error('Quantity must be positive.');
    }
    if (!(price instanceof Money)) {
      throw new Error('Price must be a Money object.');
    }

    const existingItemIndex = this._items.findIndex(item => item.id === productId);
    if (existingItemIndex > -1) {
      const existingItem = this._items[existingItemIndex];
      // Assuming we update quantity and price if item already exists
      this._items[existingItemIndex] = {
        ...existingItem,
        quantity: existingItem.quantity + quantity,
        price: price // Update to new price if different
      };
    } else {
      this._items.push({ id: productId, quantity, price });
    }

    this.domainEvents.push({
      type: 'OrderItemAdded',
      occurredAt: new Date(),
      payload: { orderId: this.id, productId, quantity, price: price.amount, currency: price.currency }
    });
  }

  public pay(): void {
    if (this.status !== 'PENDING') {
      throw new Error('Order cannot be paid unless it is PENDING.');
    }
    if (this._items.length === 0) {
      throw new Error('Cannot pay for an empty order.');
    }
    this.status = 'PAID';
    this.domainEvents.push({
      type: 'OrderPaid',
      occurredAt: new Date(),
      payload: { orderId: this.id, total: this.getTotal().amount, currency: this.getTotal().currency }
    });
  }

  public ship(): void {
    if (this.status !== 'PAID') {
      throw new Error('Order cannot be shipped unless it is PAID.');
    }
    this.status = 'SHIPPED';
    this.domainEvents.push({
      type: 'OrderShipped',
      occurredAt: new Date(),
      payload: { orderId: this.id }
    });
  }

  public cancel(): void {
    if (this.status === 'SHIPPED' || this.status === 'CANCELLED') {
      throw new Error('Cannot cancel a SHIPPED or already CANCELLED order.');
    }
    this.status = 'CANCELLED';
    this.domainEvents.push({
      type: 'OrderCancelled',
      occurredAt: new Date(),
      payload: { orderId: this.id }
    });
  }

  public getTotal(): Money {
    if (this._items.length === 0) {
      return Money.of(0, 'USD'); // Default currency if no items
    }

    const firstCurrency = this._items[0].price.currency;
    const total = this._items.reduce((sum, item) => {
      if (item.price.currency !== firstCurrency) {
        throw new Error('Order contains items with mixed currencies.');
      }
      return sum.add(Money.of(item.quantity * item.price.amount, item.price.currency));
    }, Money.of(0, firstCurrency));

    return total;
  }

  public getDomainEvents(): DomainEvent[] {
    const events = [...this.domainEvents];
    this.domainEvents = []; // Clear events after retrieval
    return events;
  }
}

