export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreakerOpenError extends Error {
  constructor(message: string = 'Circuit breaker is open') {
    super(message);
    this.name = 'CircuitBreakerOpenError';
  }
}

export class CircuitBreaker {
  private _state: CircuitState = 'CLOSED';
  private failureCount: number = 0;
  private lastFailureTime: number = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;

  constructor(options?: CircuitBreakerOptions) {
    this.failureThreshold = options?.failureThreshold ?? 5;
    this.resetTimeoutMs = options?.resetTimeoutMs ?? 30000; // 30 seconds
  }

  get state(): CircuitState {
    return this._state;
  }

  getState(): CircuitState {
    return this._state;
  }

  recordSuccess(): void {
    if (this._state === 'HALF_OPEN') {
      this._state = 'CLOSED';
    }
    this.failureCount = 0;
    this.lastFailureTime = 0;
  }

  recordFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this._state === 'HALF_OPEN' || (this._state === 'CLOSED' && this.failureCount >= this.failureThreshold)) {
      this._state = 'OPEN';
    }
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this._state === 'OPEN') {
      if (Date.now() - this.lastFailureTime > this.resetTimeoutMs) {
        this._state = 'HALF_OPEN';
      } else {
        throw new CircuitBreakerOpenError();
      }
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }
}

export class ApiError extends Error {
  readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly circuitBreaker?: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker;
  }

  private async makeRequest<T>(
    url: string,
    method: 'GET',
    options?: RequestOptions,
  ): Promise<T> {
    const abortController = new AbortController();
    const timeoutId = options?.timeoutMs
      ? setTimeout(() => abortController.abort(), options.timeoutMs)
      : undefined;

    try {
      const response = await fetch(url, {
        method: method,
        headers: options?.headers,
        signal: abortController.signal,
      });

      if (!response.ok) {
        throw new ApiError(response.statusText || 'API request failed', response.status);
      }

      return (await response.json()) as T;
    } catch (error: any) {
      if (error.name === 'AbortError') {
        throw new ApiError('Request timed out', 408);
      }
      throw error;
    } finally {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    }
  }

  async get<T>(url: string, options?: RequestOptions): Promise<T> {
    const action = () => this.makeRequest<T>(url, 'GET', options);

    if (this.circuitBreaker) {
      return this.circuitBreaker.execute(action);
    } else {
      return action();
    }
  }
}

