  constructor(message: string = 'Circuit breaker is open') {
    super(message);
    this.name = 'CircuitBreakerOpenError';
  }
}

export class CircuitBreaker {
  private _state: CircuitState = 'CLOSED';
  private failureCount: number = 0;
  private lastFailureTime: number = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;

  constructor(options?: CircuitBreakerOptions) {
    this.failureThreshold = options?.failureThreshold ?? 5;
    this.resetTimeoutMs = options?.resetTimeoutMs ?? 30000;
  }

  public get state(): CircuitState {
    return this._state;
  }

  public getState(): CircuitState {
    return this._state;
  }

  public recordSuccess(): void {
    if (this._state === 'HALF_OPEN') {
      this._state = 'CLOSED';
    }
    this.failureCount = 0;
    this.lastFailureTime = 0;
  }

  public recordFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this._state === 'CLOSED' && this.failureCount >= this.failureThreshold) {
      this._state = 'OPEN';
    }
  }

  public async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this._state === 'OPEN') {
      const now = Date.now();
      if (now - this.lastFailureTime > this.resetTimeoutMs) {
        this._state = 'HALF_OPEN';
      } else {
        throw new CircuitBreakerOpenError();
      }
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error: unknown) {
      this.recordFailure();
      throw error;
    }
  }
}

export class ApiError extends Error {
  public readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly circuitBreaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker ?? new CircuitBreaker();
  }

  public async get<T>(url: string, options?: RequestOptions): Promise<T> {
    const fetchAction = async (): Promise<T> => {
      const controller = new AbortController();
      const timeout = options?.timeoutMs ?? 10000; // Default to 10 seconds
      const timeoutId = setTimeout(() => controller.abort(), timeout);

      try {
        const response = await fetch(url, {
          method: 'GET',
          headers: options?.headers,
          signal: controller.signal,
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          const errorText = await response.text();
          throw new ApiError(errorText || response.statusText, response.status);
        }

        return (await response.json()) as T;
      } catch (error: unknown) {
        clearTimeout(timeoutId);
        if (error instanceof Error && error.name === 'AbortError') {
          throw new ApiError('Request timed out', 408);
        }
        throw error;
      }
    };

    return this.circuitBreaker.execute(fetchAction);
  }
}

