import * as bcrypt from 'bcrypt';
import * as jwt from 'jsonwebtoken';

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

export class AuthService implements IAuthService {
  private users: Map<string, { id: string; email: string; passwordHash: string; role?: string }> = new Map();
  private loginAttempts: Map<string, { count: number; lastAttempt: number }> = new Map();
  private readonly SALT_ROUNDS = 10;
  private readonly MAX_ATTEMPTS = 5;
  private readonly ATTEMPT_WINDOW_MS = 15 * 60 * 1000;

  async hashPassword(password: string): Promise<string> {
    return bcrypt.hash(password, this.SALT_ROUNDS);
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    return bcrypt.compare(password, hash);
  }

  async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    return jwt.sign(payload, secret, { expiresIn: '1h' });
  }

  async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const { email, password, ip } = request;
    if (!email || !password || !ip) {
      return { status: 400, body: { error: 'Missing credentials' } };
    }

    const attemptKey = `${email}_${ip}`;
    const now = Date.now();
    const attempts = this.loginAttempts.get(attemptKey) || { count: 0, lastAttempt: 0 };

    if (attempts.count >= this.MAX_ATTEMPTS && now - attempts.lastAttempt < this.ATTEMPT_WINDOW_MS) {
      return { status: 429, body: { error: 'Too many attempts' } };
    }

    const user = this.users.get(email);
    if (!user) {
      this.updateAttempts(attemptKey, attempts, now);
      return { status: 401, body: { error: 'Invalid credentials' } };
    }

    const isValid = await this.verifyPassword(password, user.passwordHash);
    if (!isValid) {
      this.updateAttempts(attemptKey, attempts, now);
      return { status: 401, body: { error: 'Invalid credentials' } };
    }

    this.loginAttempts.delete(attemptKey);
    const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, 'secret_key');
    return { status: 200, body: { token } };
  }

  private updateAttempts(key: string, attempts: { count: number; lastAttempt: number }, now: number): void {
    const newAttempts = {
      count: attempts.count + 1,
      lastAttempt: now
    };
    this.loginAttempts.set(key, newAttempts);
  }
}

