import crypto from 'node:crypto';
import util from 'node:util';

const scrypt = util.promisify(crypto.scrypt);
const randomBytes = util.promisify(crypto.randomBytes);

export class AuthService implements IAuthService {
  private rateLimits = new Map<string, { count: number; expiresAt: number }>();
  private userStore = new Map<string, { email: string; passwordHash: string }>();

  async hashPassword(password: string): Promise<string> {
    const salt = (await randomBytes(16)).toString('hex');
    const derivedKey = (await scrypt(password, salt, 64)) as Buffer;
    return `${salt}:${derivedKey.toString('hex')}`;
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    const [salt, key] = hash.split(':');
    const derivedKey = (await scrypt(password, salt, 64)) as Buffer;
    return crypto.timingSafeEqual(Buffer.from(key, 'hex'), derivedKey);
  }

  async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    const header = { alg: 'HS256', typ: 'JWT' };
    const encodedHeader = Buffer.from(JSON.stringify(header)).toString('base64url');
    const encodedPayload = Buffer.from(JSON.stringify(payload)).toString('base64url');
    const signature = crypto
      .createHmac('sha256', secret)
      .update(`${encodedHeader}.${encodedPayload}`)
      .digest('base64url');
    return `${encodedHeader}.${encodedPayload}.${signature}`;
  }

  async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const { email, password, ip } = request;
    if (!email || !password || !ip) return { status: 400, body: { error: 'Missing credentials' } };

    const ipLimit = this.rateLimits.get(ip);
    if (ipLimit && ipLimit.expiresAt > Date.now()) {
      if (ipLimit.count >= 5) return { status: 429, body: { error: 'Too many attempts' } };
      this.rateLimits.set(ip, { ...ipLimit, count: ipLimit.count + 1 });
    } else {
      this.rateLimits.set(ip, { count: 1, expiresAt: Date.now() + 15 * 60 * 1000 });
    }

    const user = this.userStore.get(email);
    if (!user) return { status: 401, body: { error: 'Invalid credentials' } };

    const isValid = await this.verifyPassword(password, user.passwordHash);
    if (!isValid) return { status: 401, body: { error: 'Invalid credentials' } };

    const token = await this.generateToken({ id: crypto.randomUUID(), email }, process.env.JWT_SECRET!);
    return {
      status: 200,
      body: { token, user: { email } },
      headers: {
        'Set-Cookie': `token=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=900`
      }
    };
  }
}

