      throw new Error('Password must be at least 8 characters');
    }
    const salt = crypto.randomBytes(16);
    const derived = await new Promise<Buffer>((resolve, reject) => {
      crypto.scrypt(password, salt, 64, { N: 16384 }, (err, key) => (err ? reject(err) : resolve(key)));
    });
    return `scrypt$${salt.toString('hex')}$${derived.toString('hex')}`;
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    try {
      const [scheme, saltHex, keyHex] = hash.split('$');
      if (scheme !== 'scrypt' || !saltHex || !keyHex) return false;
      const derived = await new Promise<Buffer>((resolve, reject) => {
        crypto.scrypt(password, Buffer.from(saltHex, 'hex'), 64, { N: 16384 }, (err, key) =>
          err ? reject(err) : resolve(key)
        );
      });
      const expected = Buffer.from(keyHex, 'hex');
      if (derived.length !== expected.length) return false;
      return crypto.timingSafeEqual(derived, expected);
    } catch {
      return false;
    }
  }

  async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    if (!secret || secret.length < 32) throw new Error('Secret must be at least 32 characters');
    const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
    const body = b64url(
      Buffer.from(
        JSON.stringify({
          sub: payload.id,
          email: payload.email,
          role: payload.role ?? 'user',
          iat: Math.floor(Date.now() / 1000),
          exp: Math.floor(Date.now() / 1000) + 15 * 60, // 15-minute access token
        })
      )
    );
    const sig = crypto.createHmac('sha256', secret).update(`${header}.${body}`).digest('base64url');
    return `${header}.${body}.${sig}`;
  }

  private checkRateLimit(ip: string): boolean {
    const now = Date.now();
    const rec = this.attempts.get(ip);
    if (!rec || now - rec.lockedUntil > this.windowMs) {
      this.attempts.set(ip, { count: 1, lockedUntil: now });
      return true;
    }
    rec.count += 1;
    return rec.count <= this.rateLimit;
  }

  private recordFailure(ip: string): void {
    const rec = this.attempts.get(ip) ?? { count: 0, lockedUntil: Date.now() };
    rec.count += 1;
    if (rec.count >= this.maxAttempts) rec.lockedUntil = Date.now() + this.lockoutMs;
    this.attempts.set(ip, rec);
  }

  async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const ip = request.ip ?? 'unknown';
    try {
      if (!this.checkRateLimit(ip)) {
        return { status: 429, body: { error: 'RATE_LIMITED', message: 'Too many requests. Try again later.' } };
      }
      const locked = this.attempts.get(ip);
      if (locked && locked.lockedUntil > Date.now()) {
        return { status: 429, body: { error: 'ACCOUNT_LOCKED', message: 'Too many failed attempts. Try again later.' } };
      }
      const email = (request.email ?? '').toLowerCase().trim();
      const password = request.password ?? '';
      if (!email || !password || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
