      const secret = process.env.JWT_SECRET ?? '';
      if (secret.length < 32) {
        return { status: 500, body: { error: 'INTERNAL_SERVER_ERROR', message: 'Authentication unavailable.' } };
      }
      const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, secret);
