        status: 200,
        body: {
          data: { token, tokenType: 'Bearer', expiresIn: 900, user: { id: user.id, email: user.email, role: user.role } },
        },
      };
    } catch (err) {
      console.error(JSON.stringify({ level: 'error', msg: 'login_failed', ip, err: (err as Error).message }));
      return { status: 500, body: { error: 'INTERNAL_SERVER_ERROR', message: 'An unexpected error occurred.' } };
    }
  }
}

