  }

  add(other: Money): Money {
    if (other.currency !== this.currency) {
      throw new Error(`Currency mismatch: ${this.currency} vs ${other.currency}`);
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus = 'PENDING';
  private _items: OrderItem[] = [];
  private _events: any[] = [];

  constructor(id: string, customerId: string) {
    if (!id || !customerId) throw new Error('Order id and customerId are required');
    this.id = id;
    this.customerId = customerId;
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') throw new Error('Cannot modify a non-pending order');
    if (!productId) throw new Error('productId is required');
    if (!Number.isInteger(quantity) || quantity <= 0) throw new Error('Quantity must be a positive integer');
    const existing = this._items.find((i) => i.id === productId);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this._items.push({ id: productId, quantity, price });
    }
    this._events.push({ type: 'ItemAdded', orderId: this.id, productId, quantity });
  }

  pay(): void {
    if (this._status !== 'PENDING') throw new Error(`Cannot pay order in status ${this._status}`);
    if (this._items.length === 0) throw new Error('Cannot pay an empty order');
    this._status = 'PAID';
    this._events.push({ type: 'OrderPaid', orderId: this.id, total: this.getTotal() });
  }

  ship(): void {
    if (this._status !== 'PAID') throw new Error(`Cannot ship order in status ${this._status}`);
    this._status = 'SHIPPED';
    this._events.push({ type: 'OrderShipped', orderId: this.id });
  }

  cancel(): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new Error(`Cannot cancel order in status ${this._status}`);
    }
    this._status = 'CANCELLED';
    this._events.push({ type: 'OrderCancelled', orderId: this.id });
  }

  getTotal(): Money {
    if (this._items.length === 0) return new Money(0, 'USD');
    return this._items
      .map((i) => new Money(i.price.amount * i.quantity, i.price.currency))
      .reduce((sum, m) => sum.add(m));
  }

  getDomainEvents(): any[] {
    return [...this._events];
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

// In-memory implementation of IOrderRepository (self-contained).
export class InMemoryOrderRepository implements IOrderRepository {
  private store = new Map<string, Order>();

  async findById(id: string): Promise<Order | null> {
    return this.store.get(id) ?? null;
  }

  async save(order: Order): Promise<void> {
    this.store.set(order.id, order);
  }
}

