export class CircuitBreaker {
  private _state: CircuitState = 'CLOSED';
  private _failures = 0;
  private readonly _failureThreshold: number;
  private readonly _resetTimeoutMs: number;
  private _openedAt: number | null = null;

  constructor(options: CircuitBreakerOptions = {}) {
    this._failureThreshold = options.failureThreshold ?? 3;
    this._resetTimeoutMs = options.resetTimeoutMs ?? 30000;
  }

  get state(): CircuitState {
    if (this._state === 'OPEN' && this._openedAt !== null && Date.now() - this._openedAt >= this._resetTimeoutMs) {
      this._state = 'HALF_OPEN';
    }
    return this._state;
  }

  getState(): CircuitState { return this.state; }

  recordSuccess(): void {
    this._failures = 0;
    this._state = 'CLOSED';
    this._openedAt = null;
  }

  recordFailure(): void {
    this._failures += 1;
    if (this._state === 'HALF_OPEN' || this._failures >= this._failureThreshold) {
      this._state = 'OPEN';
      this._openedAt = Date.now();
    }
  }

  execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.state === 'OPEN') {
      return Promise.reject(new Error('Circuit breaker is open'));
    }
    try {
      return action().then(
        (result) => { this.recordSuccess(); return result; },
        (error) => { this.recordFailure(); throw error; }
      );
    } catch (error) { return Promise.reject(error); }
  }
}

