export class ResilientHttpClient {
 private readonly circuitBreaker: CircuitBreaker;
 constructor(circuitBreaker?: CircuitBreaker) { this.circuitBreaker = circuitBreaker ?? new CircuitBreaker(); }

 async get<T>(url: string, options: RequestOptions = {}): Promise<T> {
   return this.circuitBreaker.execute<T>(async () => {
     const controller = new AbortController();
     const timeoutId = setTimeout(() => controller.abort(), options.timeoutMs ?? 10000);
     try {
       const res = await fetch(url, { headers: options.headers, signal: controller.signal });
       if (!res.ok) {
         const text = await res.text().catch(() => '');
         throw new ApiError(text || res.statusText || `HTTP ${res.status}`, res.status);
       }
       const text = await res.text();
       if (!text) return undefined as T;
       return JSON.parse(text) as T;
     } finally {
       clearTimeout(timeoutId);
     }
   });
 }
}

